-- pet_levelstats: re-curve the level 81-255 base stats onto the player HP curve.
--
-- Depends on the revision that restores the 81-255 rows; apply that one first.
--
-- The live 81-255 rows extend the level 60-80 slope linearly, while player_class_stats
-- and creature_classlevelstats were both rescaled superlinearly for the 255 cap. The
-- result is that pet base HP tracks player base HP at ~70% at level 80 but only ~26%
-- at level 255 (entry 1: 5161 vs 7324 at level 80, 24586 vs 96224 at 255).
--
-- This rescales the affected columns so the level-80 pet:player relationship holds at
-- every level: value(L) = value(80) * BaseHP(L) / BaseHP(80), taken from
-- player_class_stats for class 3 (hunter). Level 80 itself is untouched, so nothing
-- below the current cap changes. The reference curve grows 13.14x from 80 to 255;
-- the class spread is 11.24x-13.16x, so one reference curve covers all pet owners.
--
-- Columns deliberately left on the linear values:
--   armor  - already lands within 5% of creature_classlevelstats at 255 (62109 vs 65197);
--            armor is diminishing-returns, a 13x multiply would make pets near-immune.
--   sta, inte, agi - inert for pets. Guardian::UpdateMaxHealth/UpdateMaxPower/UpdateArmor
--            use (GetStat - GetCreateStat), so raising the base raises both sides of the
--            subtraction and changes nothing. Pet HP comes from the hp column plus
--            inherited owner stamina.
--   str    - feeds AP as 2*str, but the live extrapolation is already steeper than the
--            player curve for some entries (imp: 16.9x vs 13.14x), so a uniform rescale
--            would nerf them. Left alone pending a deliberate AP pass.
--
-- Changed: hp for all 35 entries, plus min_dmg/max_dmg for the six summon pets that
-- have non-zero weapon damage (hunter pets derive theirs from petlevel in code).

DELETE FROM `pet_levelstats` WHERE `level` BETWEEN 81 AND 255;
INSERT INTO `pet_levelstats` (`creature_entry`, `level`, `hp`, `mana`, `armor`, `str`, `agi`, `sta`, `inte`, `spi`, `min_dmg`, `max_dmg`) VALUES
